import { useNavigate } from 'react-router-dom';

export default function Navbar() {
  const navigate = useNavigate();
  const username = localStorage.getItem('username');

  const logout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('username');
    navigate('/');
  };

  return (
    <div style={styles.navbar}>
      <h2 style={styles.logo}>🌐 SocialApp</h2>
      <div style={styles.right}>
        <span style={styles.username}>👤 {username}</span>
        <button style={styles.button} onClick={logout}>Logout</button>
      </div>
    </div>
  );
}

const styles = {
  navbar: { display: 'flex', justifyContent: 'space-between',
    alignItems: 'center', padding: '12px 24px',
    background: '#4f46e5', color: '#fff',
    position: 'sticky', top: 0, zIndex: 100 },
  logo: { margin: 0, fontSize: '20px' },
  right: { display: 'flex', alignItems: 'center', gap: '16px' },
  username: { fontSize: '14px' },
  button: { padding: '8px 16px', background: '#fff',
    color: '#4f46e5', border: 'none', borderRadius: '8px',
    cursor: 'pointer', fontWeight: 'bold' },
};
